/*-------------------------------------------------------------------------------------------------------------------------------------------------------AUTOR: ROBERTO RECIFEDESCRICAO: CONFERENCIA DE ESTOQUEDATA: 08/05/2023-------------------------------------------------------------------------------------------------------------------------------------------------------SP_CONFERENCIA_NF_CTE '01/01/2023','08/05/2023'-------------------------------------------------------------------------------------------------------------------------------------------------------DROP PROCEDURE SP_CONFERENCIA_NF_CTE-------------------------------------------------------------------------------------------------------------------------------------------------------*/CREATE PROCEDURE [dbo].[SP_CONFERENCIA_NF_CTE](	@MV_PAR01		VARCHAR(10),	@MV_PAR02		VARCHAR(10)) AS-------------------------------------------------------------------------------------------------------------------------------------------------------SELECT @MV_PAR01=SUBSTRING(@MV_PAR01,7,4)+SUBSTRING(@MV_PAR01,4,2)+SUBSTRING(@MV_PAR01,1,2)SELECT @MV_PAR02=SUBSTRING(@MV_PAR02,7,4)+SUBSTRING(@MV_PAR02,4,2)+SUBSTRING(@MV_PAR02,1,2)-------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT ON--------------------------------------------------------------------------------------------------------------------------------------------------------- VENDAS-------------------------------------------------------------------------------------------------------------------------------------------------------SELECT	CONVERT(VARCHAR(10),CONVERT(DATETIME,D2_EMISSAO),103) AS 'EMISSAO',		D2_DOC AS 'NOTA FISCAL',		D2_CLIENTE AS 'CLIENTE',		D2_LOJA AS 'LOJA',		A1_NOME AS 'NOME',		D2_ITEM AS 'ITEM',		D2_COD AS 'PRODUTO',		B1_DESC AS 'DESCRICAO',		D2_QUANT AS 'QUANTIDADE',		D2_PRCVEN 'VLR UNITARIO',		D2_TOTAL AS 'TOTAL',		D2_VALICM AS 'VLR ICMS',		'VLR CTE'=ISNULL((SELECT TOP 1 F1_VALBRUT FROM SF1010 WHERE F1_FILIAL='0101' AND D_E_L_E_T_<>'*' AND F1_TIPO='C' AND F1_DOC+F1_SERIE+F1_FORNECE IN (SELECT D1_DOC+D1_SERIE+D1_FORNECE FROM SD1010 WHERE D1_FILIAL='0101' AND D1_NFORI=D2_DOC AND D1_SERIORI=D2_SERIE AND D2_ITEM='01' AND D_E_L_E_T_<>'*')),0),		'NF CTE'=ISNULL((SELECT TOP 1 D1_DOC+'/'+D1_SERIE FROM SD1010 WHERE D1_FILIAL='0101' AND D1_TIPO='C' AND D1_NFORI=D2_DOC AND D1_SERIORI=D2_SERIE AND D2_ITEM='01' AND D_E_L_E_T_<>'*'),''),		'TRANSP.'=ISNULL((SELECT TOP 1 D1_FORNECE+'/'+D1_LOJA+'-'+(SELECT A2_NOME FROM SA2010 WHERE A2_FILIAL='01' AND A2_COD=D1_FORNECE AND A2_LOJA=D1_LOJA AND D2_ITEM='01' AND D_E_L_E_T_<>'*') FROM SD1010 WHERE D1_FILIAL='0101' AND D1_NFORI=D2_DOC AND D2_ITEM='01' AND D1_TIPO='C' AND D1_SERIORI=D2_SERIE AND D_E_L_E_T_<>'*'),''),		'DESPESAS'=ISNULL((SELECT TOP 1 F2_DESPESA+F2_FRETE+F2_SEGURO FROM SF2010 WHERE F2_FILIAL='0101' AND F2_DOC=D2_DOC AND F2_SERIE=D2_SERIE AND D2_CLIENTE=F2_CLIENTE AND D2_LOJA=F2_LOJA AND D2_ITEM='01' AND D_E_L_E_T_<>'*'),0),		D2_LOCAL 'ALMOX',		D2_TES AS 'TES',		D2_CF AS 'CFO',		D2_PEDIDO AS 'PEDIDO'		FROM	SD2010 SD2,SB1010 SB1,SA1010 SA1WHERE	SD2.D2_FILIAL='0101'		AND SD2.D2_COD=SB1.B1_COD		AND SD2.D2_EMISSAO BETWEEN @MV_PAR01 AND @MV_PAR02		AND SD2.D2_CLIENTE=SA1.A1_COD		AND SD2.D2_LOJA=SA1.A1_LOJA		AND SB1.B1_FILIAL=''		AND SD2.D_E_L_E_T_<>'*'		AND SB1.D_E_L_E_T_<>'*'		AND SA1.D_E_L_E_T_<>'*'ORDER BY D2_EMISSAO,D2_DOC,D2_ITEM-------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT OFF-------------------------------------------------------------------------------------------------------------------------------------------------------